"""Text-to-SQL harness: draft -> execute -> evidence-grounded repair.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}      (hint is BIRD's evidence; "" for Spider)
  env.chat(messages, max_tokens=None) -> str     policy call (capped per task: env.max_calls)
  env.schema(db_id) -> str                       CREATE statements of the database
  env.execute(sql, max_rows=20) -> dict          read-only run: {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if the dataset ships them, else ""
  env.prompt(name) -> str                        text of a file in this harness
  env.config -> dict                             parsed config.json
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
IDENT = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")
FROM_JOIN = re.compile(r"\b(?:from|join)\s+([\"'`\[]?[A-Za-z_][A-Za-z_0-9]*)", re.I)
LITERAL = re.compile(r"'((?:[^']|'')*)'")
STRIP_TRAIL = re.compile(r"[;\s]+$")


def extract_sql(text):
    text = text or ""
    blocks = [b.strip() for b in SQL_BLOCK.findall(text) if b.strip()]
    if blocks:
        cand = blocks[-1]
    else:
        # tolerate an unterminated fence or bare SQL mixed with prose
        m = re.search(r"```(?:sql|sqlite)?\s*(.*)$", text, re.S | re.I)
        if m and m.group(1).strip():
            cand = m.group(1).strip()
        else:
            lines = [ln for ln in text.splitlines()
                     if re.match(r"\s*(select|with|insert|update|delete|pragma)\b", ln, re.I)]
            cand = "\n".join(lines) if lines else text
    return STRIP_TRAIL.sub("", cand).strip()


def _tables(sql):
    seen, out = set(), []
    for t in FROM_JOIN.findall(sql or ""):
        t = t.strip('"\'`[]')
        k = t.lower()
        if k not in seen:
            seen.add(k)
            out.append(t)
    return out


def _safe_execute(env, sql, max_rows=20):
    try:
        r = env.execute(sql, max_rows=max_rows)
    except Exception as exc:  # never let a probe kill the task
        return {"ok": False, "error": str(exc), "rows": [], "columns": [], "n_rows": 0}
    if not isinstance(r, dict):
        return {"ok": False, "error": "no result", "rows": [], "columns": [], "n_rows": 0}
    return r


def _evidence(env, db_id, sql, limit_tables=3, sample_rows=6):
    """Real stored values for the tables/literals the draft touches."""
    parts = []
    lits = []
    for m in LITERAL.finditer(sql or ""):
        v = m.group(1).replace("''", "'")
        if v and v not in lits:
            lits.append(v)
    for t in _tables(sql)[:limit_tables]:
        r = _safe_execute(env, 'SELECT * FROM "%s" LIMIT %d' % (t, sample_rows), max_rows=sample_rows)
        if r.get("ok"):
            cols = r.get("columns") or []
            rows = r.get("rows") or []
            parts.append("Sample rows of %s (%s):\n%s" % (t, ", ".join(map(str, cols)), rows))
        for v in lits[:4]:
            core = v.strip("%").strip()
            if len(core) < 3:
                continue
            probe = ('SELECT * FROM "%s" WHERE CAST("%s" AS TEXT) LIKE %s LIMIT 3'
                     % (t, "", ""))  # placeholder replaced below
            for c in (r.get("columns") or [])[:12]:
                q = ("SELECT \"%s\" FROM \"%s\" WHERE CAST(\"%s\" AS TEXT) LIKE '%%%s%%' LIMIT 3"
                     % (c, t, c, core.replace("'", "''")))
                pr = _safe_execute(env, q, max_rows=3)
                if pr.get("ok") and pr.get("rows"):
                    parts.append("Stored values in %s.%s matching %r: %s"
                                 % (t, c, core, [row[0] for row in pr["rows"]]))
            del probe
    return "\n".join(parts)[:2500]


REPAIR_TMPL = """Your previous query for this question did not produce a usable answer.

Previous query:
{sql}

Execution outcome: {outcome}

Grounding evidence taken from the actual database (real stored values):
{evidence}

Write ONE corrected SQLite query. Checklist:
- String literals must match how values are actually stored (exact spelling/case/spacing); use LIKE '%...%' only when the question asks for a substring.
- Verify every join key against the schema; do not join on a column that merely looks similar.
- For "does not have any / never / no ..." prefer NOT EXISTS or a LEFT JOIN ... IS NULL over NOT IN (NULLs break NOT IN).
- Select exactly the columns the question asks for; "details"/"information about X" usually means all columns of that entity's table.
- Keep DISTINCT / GROUP BY / ORDER BY / LIMIT only when the question requires them.
Return only the corrected query in a single ```sql block."""


def solve(task, env):
    cfg = env.config or {}
    budget = int(cfg.get("max_tokens", 800))
    db_id = task["db_id"]
    user = "Database: %s\n\nSchema:\n%s\n\nQuestion: %s" % (db_id, env.schema(db_id), task["question"])
    desc = ""
    try:
        desc = env.descriptions(db_id) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\n\nColumn notes:\n" + desc.strip()[:2000]
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]

    messages = [{"role": "system", "content": env.prompt("system_prompt.md")},
                {"role": "user", "content": user}]
    reply = env.chat(messages, max_tokens=budget)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": "SELECT 1"}

    calls_left = getattr(env, "max_calls", 2) - 1
    if calls_left <= 0 or not cfg.get("repair", True):
        return {"sql": sql}

    res = _safe_execute(env, sql, max_rows=20)
    ok = bool(res.get("ok"))
    nrows = res.get("n_rows", len(res.get("rows") or []))
    if ok and nrows > 0:
        return {"sql": sql}

    if ok:
        outcome = "ran successfully but returned 0 rows (the expected answer is very likely non-empty)"
    else:
        outcome = "ERROR: %s" % str(res.get("error"))[:400]
    ev = _evidence(env, db_id, sql) if cfg.get("probe_values", True) else ""
    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": REPAIR_TMPL.format(sql=sql, outcome=outcome,
                                                      evidence=ev or "(none available)")},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=budget)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    res2 = _safe_execute(env, sql2, max_rows=20)
    if res2.get("ok") and res2.get("n_rows", len(res2.get("rows") or [])) > 0:
        return {"sql": sql2}
    if not ok and res2.get("ok"):
        return {"sql": sql2}
    if ok and not res2.get("ok"):
        return {"sql": sql}
    return {"sql": sql2}

